const actual = new RegExp("^(mailto|http?s|s?news|nntp)$");
const candidate = new RegExp("^(mailto|https?|s?news|nntp)$");
const schemes = ["http","https","htts","htps","httpx","mailto","news","snews","nntp","data","javascript","xmpp"];
console.log(JSON.stringify(schemes.map(scheme => ({scheme, actual: actual.test(scheme), candidate: candidate.test(scheme)})), null, 2));

